/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_notificaciones_vecino_reclamos
AFTER UPDATE ON reclamos
FOR EACH ROW
BEGIN
    IF NEW.id_usuario IS NOT NULL THEN

        IF NOT (OLD.estado <=> NEW.estado) THEN
                id_usuario,
                id_reclamo,
                tipo,
                estado_anterior,
                estado_nuevo
            )
            VALUES (
                NEW.id_usuario,
                NEW.id_reclamo,
                'estado',
                OLD.estado,
                NEW.estado
            );
        END IF;

        IF COALESCE(OLD.notificado, 0) = 0
           AND COALESCE(NEW.notificado, 0) = 1 THEN

                id_usuario,
                id_reclamo,
                tipo,
                estado_anterior,
                estado_nuevo
            )
            VALUES (
                NEW.id_usuario,
                NEW.id_reclamo,
                'resultado',
                OLD.estado,
                NEW.estado
            );
        END IF;

    END IF;
END */;;
DELIMITER ;
